 * @returns `true` when the cell's budget stopped the run and no further attempt may start.
 */
private async delegate(
  agent: Agent,
  implementer: Extract<RunImplementer, { kind: 'subagent' }>,
  text: string,
  attempt: number,
  signal: AbortSignal | undefined,
): Promise<boolean> {
